pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(address caller) internal {
        uint balBefore = address(c).balance;
        caller = c.Owner();
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted || address(c).balance <= balBefore);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
